-- 預存程序：新增訂單並回傳新 OrderId
CREATE PROCEDURE usp_CreateOrder
    @CustomerId INT,
    @Amount     DECIMAL(10,2),
    @NewOrderId INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        INSERT INTO Orders (CustomerId, Amount, OrderDate)
        VALUES (@CustomerId, @Amount, GETDATE());
        SET @NewOrderId = SCOPE_IDENTITY();
    END TRY
    BEGIN CATCH
        SET @NewOrderId = -1;
        THROW;
    END CATCH
END;
GO

-- Trigger：記錄薪資異動稽核
CREATE TRIGGER trg_AuditSalaryChange
ON Employees
AFTER UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF UPDATE(Salary)
    BEGIN
        INSERT INTO SalaryAudit (EmpId, OldSalary, NewSalary, ChangedAt)
        SELECT d.EmpId, d.Salary, i.Salary, GETDATE()
        FROM deleted d
        INNER JOIN inserted i ON d.EmpId = i.EmpId
        WHERE d.Salary <> i.Salary;
    END
END;

