CREATE PROCEDURE usp_TransferEmployee
    @EmpId    INT,
    @NewDeptId INT,
    @Success  BIT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (SELECT 1 FROM Employees WHERE EmpId = @EmpId)
    BEGIN
        UPDATE Employees SET DeptId = @NewDeptId WHERE EmpId = @EmpId;
        SET @Success = 1;
    END
    ELSE
        SET @Success = 0;
END;
GO

-- 執行
DECLARE @ok BIT;
EXEC usp_TransferEmployee @EmpId = 5, @NewDeptId = 2, @Success = @ok OUTPUT;
SELECT @ok AS Success;

