CREATE FUNCTION dbo.fn_CalcBonus
(
    @Salary DECIMAL(10,2),
    @Rate   DECIMAL(5,2)
)
RETURNS DECIMAL(10,2)
AS
BEGIN
    RETURN @Salary * @Rate / 100;
END;
GO

-- 使用
SELECT Name, Salary, dbo.fn_CalcBonus(Salary, 10) AS Bonus
FROM Employees;

