-- 完整銀行轉帳交易（含錯誤處理）
CREATE PROCEDURE usp_Transfer
    @FromAccId INT,
    @ToAccId   INT,
    @Amount    DECIMAL(10,2)
AS
BEGIN
    SET NOCOUNT ON;

    IF @Amount <= 0
        THROW 50001, N'轉帳金額必須大於 0', 1;

    BEGIN TRANSACTION;
    BEGIN TRY
        -- 確認餘額足夠
        DECLARE @Balance DECIMAL(10,2);
        SELECT @Balance = Balance FROM Accounts WHERE AccId = @FromAccId;

        IF @Balance < @Amount
            THROW 50002, N'餘額不足', 1;

        UPDATE Accounts SET Balance = Balance - @Amount WHERE AccId = @FromAccId;
        UPDATE Accounts SET Balance = Balance + @Amount WHERE AccId = @ToAccId;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;

