    BEGIN TRY
        DELETE FROM OrderDetails WHERE OrderId = @OrderId;
        DELETE FROM Orders WHERE OrderId = @OrderId;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;

